            "text": "{\"v\":7,\"opts\":{\"origin\":[0,-1400]},\"components\":{\"in2\":{\"type\":\"in\",\"pos\":[150,-1260],\"ref\":\"in2\",\"id\":6,\"name\":\"x\"},\"nand0\":{\"type\":\"nand\",\"pos\":[400,-1240],\"ref\":\"nand0\",\"in\":[0,1],\"out\":2},\"nand1\":{\"type\":\"nand\",\"pos\":[400,-1135],\"ref\":\"nand1\",\"in\":[3,4],\"out\":5},\"out0\":{\"type\":\"out\",\"pos\":[475,-1240],\"ref\":\"out0\",\"id\":8},\"out1\":{\"type\":\"out\",\"pos\":[475,-1135],\"ref\":\"out1\",\"id\":9},\"nand2\":{\"type\":\"nand\",\"pos\":[320,-1250],\"ref\":\"nand2\",\"in\":[10,11],\"out\":12},\"nand3\":{\"type\":\"nand\",\"pos\":[320,-1125],\"ref\":\"nand3\",\"in\":[13,14],\"out\":15},\"nand4\":{\"type\":\"nand\",\"pos\":[240,-1115],\"ref\":\"nand4\",\"in\":[16,17],\"out\":18},\"pass0\":{\"type\":\"pass\",\"pos\":[190,-1125],\"ref\":\"pass0\",\"in\":19,\"out\":20},\"clock0\":{\"type\":\"clock\",\"pos\":[120,-1185],\"ref\":\"clock0\",\"id\":21,\"name\":\"c\",\"period\":2000},\"pass1\":{\"type\":\"pass\",\"pos\":[270,-1185],\"ref\":\"pass1\",\"in\":22,\"out\":23}},\"wires\":[[2,8],[5,9],[2,3],[5,1],[12,0],[15,4],[6,10],[18,14],[20,16],[20,17],[6,19],[23,11],[23,13],[21,22]]}"
