            "type": "text",
            "text": "<!DOCTYPE html>\n<html>\n<body>\n<ul>\n<li>Dhaka</li>\n<li>Rajshahi</li>\n<li>Chattogram</li>\n<li>Khulna</li>\n<li>Rangpur</li>\n<li>Barishal</li>\n<li>Sylhet</li>\n        <li>Mymensingh</li>\n</ul>\n</body>\n</html>"
