            "text": "<!DOCTYPE html>\n<html>\n<head>\n<title>Style Attribute Experiment</title>\n<style type=\"text/css\">\np {\nwidth:100px;\nheight:100px;\nfloat: left;\nmargin: 10px;\npadding: 10px;\nfont-family: sans-serif;\nfont-size: large;\nborder: 2px solid rgba (0, 0, 0, 0.2) ;\nborder-radius: 5px;\ntext-align: center;\n}\n</style>\n</head>\n<body>\n<p style=\"background-color: pink; color: darkred;\">Hello There!</p>\n<p style=\"background-color: paleturguoise; color: forestgreen;\">How are you!</p>\n<p style=\"background-color: lightskyblue; color: royalblue;\">Nice to meet you!</p>\n</body>\n</html>"
